const phases=['morning','lunch','afternoon','evening'],beatTypes={morning:'task',lunch:'relationship',afternoon:'decision',evening:'private_consequence'},threadIds=['role_material_and_note','body_consent_and_partner','cue_version_and_stage','understudy_cover_and_absence','load_recovery_and_sustainability','ensemble_power_and_status','public_exposure_and_future_work'],audIds=audiences.map(x=>x.id),coverage=[];
for(let d=1;d<=14;d++)for(let pi=0;pi<4;pi++){const ph=phases[pi],[title,problem]=days[d-1],aud=audIds[(d+pi-1)%audIds.length],ref=sourceRefs[((d-1)*4+pi)%sourceRefs.length],thread=threadIds[(d+pi-1)%threadIds.length];const phaseWork=ph==='morning'?'Morgenen etablerer hva som faktisk er lest, prøvd, avtalt eller fortsatt betinget før nye noter og tidsfrister kan gjøre antakelser til ensemblefakta.':ph==='lunch'?'Ved lunsj blir arbeidsrelasjonen synlig: partner, regi/koreografi, inspisient, cover eller kollega må kunne melde tvil og asymmetri uten at framtidige roller eller status brukes som pressmiddel.':ph==='afternoon'?'I ettermiddagen må en note, sceneversjon, partneravtale, cue eller avgrensning faktisk besluttes, men eier, betingelser og retest må være lesbare før neste gjennomløp eller forestilling.':'Om kvelden kommer den mindre synlige kostnaden fram: kroppslig slitasje, castingangst, skam, lettelse eller tvil. Privat ettervirkning holdes adskilt fra formell ensembleevidens og fortrolige opplysninger.';const base=`Dag ${d}, ${ph}: ${title}. ${problem} ${phaseWork} Spilleren må skille egen kunstnerisk tolkning fra gjeldende sceneversjon, partnerens samtykke og grense, fysisk belastning, cue- og scenehåndoff, regi/koreografi-mandat, arbeidsgiver/HMS-ansvar og rettighetsstatus. Alt som endrer handlingsrommet føres i den eksisterende \`ensemblebok_note_og_belastningslogg\` med sceneversjon, note eller bevegelsesoppgave, kilde til observasjonen, partnerpremiss, belastningsstatus, cue, beslutningseier, waiting/venting, handoff og konkret retest. En sterk kunstnerisk impuls er derfor ikke det samme som ny avtalt versjon, en tidligere partneravtale er ikke automatisk samtykke til endret kontakt, og en vellykket forestilling gjør ikke skjult smerte, cuegjeld eller uavklart rettighet ferdig. Denne dagen må også vise hvem som bærer kostnaden når note eller fravær kommer sent, hva som fortsatt kan beholdes, og hvordan bounded rework kan gjenåpne bare de berørte rolle-, partner-, cue- eller restitusjonsleddene. Neste aktør skal kunne se hva som er sant nå, hva som fortsatt kan bestrides, hvem som må svare og hvilke vilkår som må være oppfylt før status løftes. Beat-en bruker den allerede authored mail-/arbeidsgrammatikken og introduserer ingen ny dagsmotor, global reputation-runtime, samtykkemotor, medisinsk motor eller skjult castingakse.`;const a=audiences.find(x=>x.id===aud);const sc=`Situert standing på dag ${d}, ${ph}, vurderes hos \`${aud}\` langs aksen \`${a.standing_axis}\`. Her teller ${a.cares_about.join(' og ')}. Standing styrkes når spilleren gjør sceneversjon, note, partnerpremiss, belastning, cue, mandat, beslutningseier, effektkontroll og reparerbarhet synlige, og svekkes når prestisje, premierepress, framtidige roller, publikumsrespons eller frykt for å virke vanskelig brukes til å skyve usikkerhet og kostnad over på andre. ${a.cannot_grant} Standing gjelder bare denne konkrete arbeidsrelasjonen og situasjonen; den summeres aldri til en global reputation score, kan gå i motsatt retning hos andre publikum og kan senere endres når retest, partnersvar, ny note, cueprøve, belastningsoppfølging, cover-arbeid eller offentlig møte gir ny evidens. God standing i ett rom kan ikke brukes som fullmakt i et annet, og applaus eller framtidig castingmulighet kan ikke retroaktivt legitimere en uforsvarlig eller uavklart arbeidsprosess.`;coverage.push({day:d,phase:ph,beat_type:beatTypes[ph],summary:base,thread_ids:[thread],materialization_refs:[ref],standing_audience:aud,standing_consequence:sc})}
if(coverage.some(x=>x.summary.length<620||x.standing_consequence.length<500))throw Error('coverage depth');if(new Set(coverage.map(x=>x.summary)).size!==56||new Set(coverage.map(x=>x.standing_consequence)).size!==56)throw Error('coverage uniqueness');
